def log_calls(func):
    def wrapper(*args, **kwargs):
        print(f"Calling {func.__name__}")
        return func(*args, **kwargs)
    return wrapper

@log_calls
def gen(n):
    for i in range(n):
        yield i

for x in gen(3):
    print(x)
